<form method="post" action="<?= e(url('/portal/notifications/read')) ?>"><?= csrf_field() ?><button class="btn btn-ghost" type="submit"><?= e(__('portal.mark_read')) ?></button></form>
<?php if ($notifications === []): ?><p class="empty"><?= e(__('empty.notifications')) ?></p><?php endif; ?><?php foreach ($notifications as $note): ?><article class="card-block"><strong><?= e($note['title']) ?></strong><p><?= e($note['body']) ?></p><small><?= e(format_datetime($note['created_at'])) ?></small><?php if ($note['link']): ?><p><a href="<?= e(url($note['link'])) ?>"><?= e(__('actions.open')) ?></a></p><?php endif; ?></article><?php endforeach; ?>
